# ============================================================================
# BUILD THE CANONICAL LAND-BASED GAMBLING MULTIPLIERS
# ============================================================================
#
# The state geography and 2019 interindustry structure come from StateIO sector
# 713. National USEEIO detail ratios adapt that parent to gambling industry
# 713200. This preserves local supplier geography without substituting hotel or
# restaurant production functions for casino activity.
#
# Inputs:
#   employment_multipliers_2023.csv  generated by scripts 08 and 09
#   national_naics_ratios.csv        generated by script 13
# Optional reference-only input:
#   gambling_employment_by_state_2023.csv
#
# Outputs:
#   gambling_multipliers_2023.csv
#   employment_multipliers_2023_with_gambling.csv
# ============================================================================

library(tidyverse)

employment_file <- Sys.getenv(
  "GEMS_EMPLOYMENT_MULTIPLIERS_FILE",
  unset = "employment_multipliers_2023.csv"
)
ratio_file <- Sys.getenv(
  "GEMS_NATIONAL_RATIO_FILE",
  unset = "national_naics_ratios.csv"
)
gambling_employment_file <- Sys.getenv(
  "GEMS_GAMBLING_EMPLOYMENT_FILE",
  unset = "gambling_employment_by_state_2023.csv"
)

if (!file.exists(employment_file)) stop("Missing input: ", employment_file)
if (!file.exists(ratio_file)) stop("Missing input: ", ratio_file)

employment_multipliers <- read.csv(employment_file, stringsAsFactors = FALSE)
ratios <- read.csv(ratio_file, stringsAsFactors = FALSE)

required_ratio_columns <- c(
  "calibration_role", "va_ratio", "wage_ratio", "topi_ratio", "emp_va_ratio",
  "output_indirect_ratio", "va_indirect_ratio",
  "wage_indirect_ratio", "topi_indirect_ratio"
)
if (!all(required_ratio_columns %in% names(ratios))) {
  stop("national_naics_ratios.csv is stale; rerun 13_extract_national_naics_ratios.R")
}

gambling_ratio <- ratios %>%
  filter(property_type == "713210", calibration_role == "canonical_gambling")
if (nrow(gambling_ratio) != 1) {
  stop("Expected exactly one canonical 713210 ratio row")
}

message("Building gambling multipliers from StateIO 713 and USEEIO 713200 ratios")
message("  VA direct ratio: ", round(gambling_ratio$va_ratio, 6))
message("  Compensation direct ratio: ", round(gambling_ratio$wage_ratio, 6))
message("  TOPI direct ratio: ", round(gambling_ratio$topi_ratio, 6))
message("  Jobs/VA direct ratio: ", round(gambling_ratio$emp_va_ratio, 6))

gambling_multipliers <- employment_multipliers %>%
  filter(Sector == "713") %>%
  mutate(
    Parent_Direct_VA_Coef = Direct_VA_Coef,
    Parent_Direct_Wage_Coef = Direct_Wage_Coef,
    Parent_Direct_Tax_Coef = Direct_Tax_Coef,
    Parent_Type_I_Output = Type_I_Output,
    Parent_Type_I_VA = Type_I_VA,
    Parent_Type_I_Wage = Type_I_Wage,
    Parent_Type_I_Tax = Type_I_Tax,
    Parent_Direct_Jobs_Per_1M_Output = Direct_Jobs_Per_1M_Output,

    Direct_VA_Coef = Parent_Direct_VA_Coef * gambling_ratio$va_ratio,
    Direct_Wage_Coef = Parent_Direct_Wage_Coef * gambling_ratio$wage_ratio,
    Direct_Tax_Coef = Parent_Direct_Tax_Coef * gambling_ratio$topi_ratio,
    Emp_Coef = Emp_Coef * gambling_ratio$emp_va_ratio,

    Type_I_Output = 1 + (Parent_Type_I_Output - 1) *
      gambling_ratio$output_indirect_ratio,
    Type_I_VA = Direct_VA_Coef +
      (Parent_Type_I_VA - Parent_Direct_VA_Coef) *
      gambling_ratio$va_indirect_ratio,
    Type_I_Wage = Direct_Wage_Coef +
      (Parent_Type_I_Wage - Parent_Direct_Wage_Coef) *
      gambling_ratio$wage_indirect_ratio,
    Type_I_Tax = Direct_Tax_Coef +
      (Parent_Type_I_Tax - Parent_Direct_Tax_Coef) *
      gambling_ratio$topi_indirect_ratio,

    # USEEIO supplies an open Type I model. Apply its documented supplier-side
    # ratios to the StateIO-induced increments instead of inventing a separate,
    # untraceable calibration.
    Type_II_Output = Type_I_Output +
      (Type_II_Output - Parent_Type_I_Output) *
      gambling_ratio$output_indirect_ratio,
    Type_II_VA = Type_I_VA +
      (Type_II_VA - Parent_Type_I_VA) * gambling_ratio$va_indirect_ratio,
    Type_II_Wage = Type_I_Wage +
      (Type_II_Wage - Parent_Type_I_Wage) * gambling_ratio$wage_indirect_ratio,
    Type_II_Tax = Type_I_Tax +
      (Type_II_Tax - Parent_Type_I_Tax) * gambling_ratio$topi_indirect_ratio,

    VA_M = Industry_Output_M * Direct_VA_Coef,
    Direct_Jobs_Per_1M_Output = Parent_Direct_Jobs_Per_1M_Output *
      gambling_ratio$emp_ratio,
    Type_I_Jobs_Per_1M_Output = Direct_Jobs_Per_1M_Output +
      (Type_I_VA - Direct_VA_Coef) * Indirect_Emp_Coef,
    Type_II_Jobs_Per_1M_Output = Type_I_Jobs_Per_1M_Output +
      (Type_II_VA - Type_I_VA) * Induced_Emp_Coef,
    Type_I_Emp_Mult = Type_I_Jobs_Per_1M_Output / Direct_Jobs_Per_1M_Output,
    Type_II_Emp_Mult = Type_II_Jobs_Per_1M_Output / Direct_Jobs_Per_1M_Output,
    Jobs_Per_1M_GDP_Direct = Emp_Coef,
    Jobs_Per_1M_GDP_TypeI = Type_I_Jobs_Per_1M_Output / Type_I_VA,
    Jobs_Per_1M_GDP_TypeII = Type_II_Jobs_Per_1M_Output / Type_II_VA,

    Sector = "7132",
    Sector_Name = "Gambling Industries",
    Calibration_Source = "USEEIOv2.0.1-411 713200/US relative to output-weighted 713 parent"
  ) %>%
  select(-starts_with("Parent_"))

# State QCEW gambling detail is reference/validation data only. It never
# replaces the nationally calibrated production function or direct coefficient.
if (file.exists(gambling_employment_file)) {
  gambling_reference <- read.csv(gambling_employment_file, stringsAsFactors = FALSE) %>%
    select(state_name, gambling_employment, gambling_wages, gambling_avg_wage)
  gambling_multipliers <- gambling_multipliers %>%
    left_join(gambling_reference, by = c("State" = "state_name")) %>%
    rename(
      Gambling_Employment_Actual = gambling_employment,
      Gambling_Wages_Actual = gambling_wages,
      Gambling_Avg_Wage_Actual = gambling_avg_wage
    )
}

write.csv(gambling_multipliers, "gambling_multipliers_2023.csv", row.names = FALSE)
write.csv(
  bind_rows(employment_multipliers, gambling_multipliers) %>% arrange(State, Sector),
  "employment_multipliers_2023_with_gambling.csv",
  row.names = FALSE
)

message("Saved 50 canonical gambling rows and combined multiplier data")
